from sprisk import Verdict, operator, promise, visualization


@promise(id="test_after_train", text="Every test row is later than the latest train row.")
def test_after_train(train: pl.DataFrame, test: pl.DataFrame, time_column: str):
    if train.is_empty() or test.is_empty():
        return Verdict("inconclusive", "One side has no rows.")
    latest = train[time_column].max()
    early = test.filter(pl.col(time_column) <= latest).height
    evidence = {
        "not_later_test_rows": early,
        "latest_train": str(latest),
        "earliest_test": str(test[time_column].min()),
    }
    if early:
        return Verdict("fail", f"{early} test rows are not later than {latest}.", evidence)
    return Verdict("pass", f"Every test row is later than {latest}.", evidence)


@visualization(title="Rows over time, with the cutoff")
def rows_over_time(train: pl.DataFrame, test: pl.DataFrame, time_column: str):
    figure = go.Figure()
    for name, side in (("train", train), ("test", test)):
        counts = side.group_by(time_column).len().sort(time_column)
        figure.add_bar(x=counts[time_column], y=counts["len"], name=name)
    figure.add_vline(x=test[time_column].min())
    return figure


@operator(
    id="temporal_split",
    inputs=["data"],
    outputs=["train", "test"],
    role="split",
    folds="time",
    columns={"time_column": "common.event_time", "group_column": "common.item_identity"},
    tunables={"test_fraction": {"minimum": 0.05, "maximum": 0.40, "step": 0.05}},
    promises=[test_after_train],
)
def temporal_split(
    data: pl.DataFrame,
    time_column: str,
    test_fraction: float = 0.20,
    group_column: str | None = None,
):
    """Split by time. Every train row is strictly earlier than every test row."""
    if data[time_column].null_count():
        raise ValueError(f"{time_column} has {data[time_column].null_count()} missing values")
    cutoff = data[time_column].quantile(1 - test_fraction, interpolation="lower")
    train = data.filter(pl.col(time_column) < cutoff)
    test = data.filter(pl.col(time_column) >= cutoff)
    # Train drops every item that is also in test, so no item is on both sides.
    if group_column is not None:
        train = train.filter(~pl.col(group_column).is_in(test[group_column].implode()))
    return train, test

import plotly.graph_objects as go
import polars as pl

from sprisk import Verdict, operator, promise


@promise(id="no_row_in_both", text="No test row has the same features as a train row.")
def no_row_in_both(train: pl.DataFrame, test: pl.DataFrame):
    repeated = test.join(train.unique(), on=test.columns, how="semi", nulls_equal=True).height
    evidence = {"repeated_rows": repeated, "test_rows": test.height}
    if repeated:
        return Verdict("fail", f"{repeated} test rows repeat a train row.", evidence)
    return Verdict("pass", "No test row repeats a train row.", evidence)


def rows_per_side(train: pl.DataFrame, test: pl.DataFrame) -> go.Figure:
    """Rows in train and test"""
    return go.Figure(go.Bar(x=["train", "test"], y=[train.height, test.height]))


@operator(
    id="random_split",
    inputs=["data"],
    outputs=["train", "test"],
    role="split",
    folds="plain",
    role_default=True,
    tunables={
        "test_fraction": {"minimum": 0.05, "maximum": 0.40, "step": 0.05},
        "seed": {"minimum": 0, "maximum": 10000},
    },
    promises=[no_row_in_both],
)
def random_split(data: pl.DataFrame, test_fraction: float = 0.20, seed: int = 42):
    """Shuffle rows with a fixed seed into train and test."""
    shuffled = data.sample(fraction=1.0, shuffle=True, seed=seed)
    n_test = round(shuffled.height * test_fraction)
    return shuffled.slice(n_test), shuffled.head(n_test)

import plotly.graph_objects as go
import polars as pl
from sklearn.model_selection import train_test_split

from sprisk import Verdict, operator, promise


@promise(id="no_row_in_both", text="No test row has the same features as a train row.")
def no_row_in_both(train: pl.DataFrame, test: pl.DataFrame):
    repeated = test.join(train.unique(), on=test.columns, how="semi", nulls_equal=True).height
    evidence = {"repeated_rows": repeated, "test_rows": test.height}
    if repeated:
        return Verdict("fail", f"{repeated} test rows repeat a train row.", evidence)
    return Verdict("pass", "No test row repeats a train row.", evidence)


def class_shares(train: pl.DataFrame, test: pl.DataFrame, stratify: str) -> go.Figure:
    """Class shares in train and test"""
    figure = go.Figure()
    for name, side in (("train", train), ("test", test)):
        shares = side[stratify].value_counts(normalize=True).sort(stratify)
        figure.add_bar(x=shares[stratify], y=shares["proportion"], name=name)
    return figure


@operator(
    id="stratified_split",
    inputs=["data"],
    outputs=["train", "test"],
    role="split",
    folds="plain",
    columns={"stratify": "common.target"},
    tunables={
        "test_fraction": {"minimum": 0.05, "maximum": 0.40, "step": 0.05},
        "seed": {"minimum": 0, "maximum": 10000},
    },
    promises=[no_row_in_both],
)
def stratified_split(
    data: pl.DataFrame, stratify: str, test_fraction: float = 0.20, seed: int = 42
):
    """Shuffle rows into train and test, keeping each class's share on both sides."""
    if data[stratify].null_count():
        raise ValueError(f"{stratify} has {data[stratify].null_count()} missing values")
    train_rows, test_rows = train_test_split(
        list(range(data.height)),
        test_size=test_fraction,
        random_state=seed,
        stratify=data[stratify].to_list(),
    )
    return data[sorted(train_rows)], data[sorted(test_rows)]
